import { component$, isDev } from "@builder.io/qwik";
import { QwikCityProvider, RouterOutlet } from "@builder.io/qwik-city";
import { RouterHead } from "./components/router-head/router-head";

import "./global.css";

export default component$(() => {
  return (
    <QwikCityProvider>
      <head>
        <meta charset="utf-8" />
        {!isDev && (
          <link
            rel="manifest"
            href={`${import.meta.env.BASE_URL}manifest.json`}
          />
        )}
        <RouterHead />
        <ThemeStyle />
      </head>
      <body lang="en">
        <RouterOutlet />
      </body>
    </QwikCityProvider>
  );
});

const DEFAULT_THEME = {
  primaryColor: "#00bcd4",
  fontSize: "16px",
  borderRadius: "4px",
};

interface ThemeData {
  primaryColor: string;
  fontSize: string;
  borderColor: string;
}

export const ThemeStyle = component$(() => {
  const themeVars = resolveTheme();
  return (
    <style id="theme-variables">
      {`:root {
  --primary-color: ${themeVars.primaryColor};
  --font-size: ${themeVars.fontSize};
  --border-radius: ${themeVars.borderRadius};
}`}
    </style>
  );
});

export function resolveTheme(): ThemeData {
  // Access cookies via the server-side request event
  // In Qwik, we can use getRequestEvent() to access request info during SSR
  let cookieValue: string | null = null;

  try {
    // Dynamic import to avoid issues during client-side rendering
    const { getRequestEvent } = require("@builder.io/qwik-city");
    const requestEvent = getRequestEvent();
    if (requestEvent && requestEvent.cookie) {
      const cookie = requestEvent.cookie.get("user_theme");
      if (cookie) {
        cookieValue = cookie.value;
      }
    }
  } catch {
    // Fallback: try to read from document.cookie on client side
    if (typeof document !== "undefined") {
      const match = document.cookie.match(
        /(?:^|;\s*)user_theme=([^;]*)/
      );
      if (match) {
        cookieValue = decodeURIComponent(match[1]);
      }
    }
  }

  if (cookieValue) {
    try {
      const parsed = JSON.parse(cookieValue);
      return {
        primaryColor: parsed.primaryColor || DEFAULT_THEME.primaryColor,
        fontSize: parsed.fontSize || DEFAULT_THEME.fontSize,
        borderColor: parsed.borderRadius || DEFAULT_THEME.borderRadius,
      };
    } catch {
      // Invalid JSON, use defaults
    }
  }

  return DEFAULT_THEME;
}

import { component$, isDev } from "@builder.io/qwik";
import { QwikCityProvider, RouterOutlet, server$ } from "@builder.io/qwik-city";
import { RouterHead } from "./components/router-head/router-head";

import "./global.css";

const DEFAULT_THEME = {
  primaryColor: "#00bcd4",
  fontSize: "16px",
  borderRadius: "4px",
};

export const getThemeCSS = server$(function () {
  const cookieHeader = this.request.headers.get("cookie") || "";
  const match = cookieHeader.match(/(?:^|;\s*)user_theme=([^;]*)/);
  const cookieValue = match ? decodeURIComponent(match[1]) : null;

  let theme = DEFAULT_THEME;

  if (cookieValue) {
    try {
      const parsed = JSON.parse(cookieValue);
      theme = {
        primaryColor: parsed.primaryColor || DEFAULT_THEME.primaryColor,
        fontSize: parsed.fontSize || DEFAULT_THEME.fontSize,
        borderRadius: parsed.borderRadius || DEFAULT_THEME.borderRadius,
      };
    } catch {
      // Invalid JSON, use defaults
    }
  }

  return `:root {
  --primary-color: ${theme.primaryColor};
  --font-size: ${theme.fontSize};
  --border-radius: ${theme.borderRadius};
}`;
});

export default component$(() => {
  const themeCSS = getThemeCSS();

  return (
    <QwikCityProvider>
      <head>
        <meta charset="utf-8" />
        {!isDev && (
          <link
            rel="manifest"
            href={`${import.meta.env.BASE_URL}manifest.json`}
          />
        )}
        <RouterHead />
        <style id="theme-variables">{themeCSS.value}</style>
      </head>
      <body lang="en">
        <RouterOutlet />
      </body>
    </QwikCityProvider>
  );
});

import { component$ } from "@builder.io/qwik";
import {
  routeLoader$,
  routeAction$,
  Form,
} from "@builder.io/qwik-city";

const DEFAULT_THEME = {
  primaryColor: "#00bcd4",
  fontSize: "16px",
  borderRadius: "4px",
};

export const useThemeLoader = routeLoader$(({ cookie }) => {
  const themeCookie = cookie.get("user_theme");
  if (themeCookie) {
    try {
      const parsed = JSON.parse(themeCookie.value);
      return {
        primaryColor: parsed.primaryColor || DEFAULT_THEME.primaryColor,
        fontSize: parsed.fontSize || DEFAULT_THEME.fontSize,
        borderRadius: parsed.borderRadius || DEFAULT_THEME.borderRadius,
      };
    } catch {
      // Invalid JSON
    }
  }
  return DEFAULT_THEME;
});

export const useThemeAction = routeAction$(
  (data, { cookie, redirect, fail }) => {
    const primaryColor = data.primaryColor as string;
    const fontSize = data.fontSize as string;
    const borderRadius = data.borderRadius as string;

    // Validate primaryColor: must be valid hex color code
    const hexRegex = /^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/;
    if (!primaryColor || !hexRegex.test(primaryColor)) {
      return fail(400, {
        message: "invalid primaryColor",
      });
    }

    // Validate fontSize: must start with a number and end with px, rem, or em
    const fontSizeRegex = /^\d+(\.\d+)?(px|rem|em)$/;
    if (!fontSize || !fontSizeRegex.test(fontSize)) {
      return fail(400, {
        message: "invalid fontSize",
      });
    }

    // Validate borderRadius: must start with a number and end with px, rem, em, or %
    const borderRadiusRegex = /^\d+(\.\d+)?(px|rem|em|%)$/;
    if (!borderRadius || !borderRadiusRegex.test(borderRadius)) {
      return fail(400, {
        message: "invalid borderRadius",
      });
    }

    // Set the cookie
    const themeValue = JSON.stringify({
      primaryColor,
      fontSize,
      borderRadius,
    });
    cookie.set("user_theme", themeValue, { path: "/" });

    throw redirect(302, "/theme");
  },
);

export default component$(() => {
  const theme = useThemeLoader();
  const action = useThemeAction();

  return (
    <div>
      <h1>Theme Editor</h1>

      {action.value?.message && (
        <p style={{ color: "red" }}>{action.value.message}</p>
      )}

      <Form action={action}>
        <div>
          <label for="primaryColor">Primary Color:</label>
          <input
            id="primaryColor"
            name="primaryColor"
            type="text"
            value={theme.value.primaryColor}
          />
        </div>

        <div>
          <label for="fontSize">Font Size:</label>
          <input
            id="fontSize"
            name="fontSize"
            type="text"
            value={theme.value.fontSize}
          />
        </div>

        <div>
          <label for="borderRadius">Border Radius:</label>
          <input
            id="borderRadius"
            name="borderRadius"
            type="text"
            value={theme.value.borderRadius}
          />
        </div>

        <button type="submit">Save Theme</button>
      </Form>

      <Form action="/theme/reset" method="post" spaReset>
        <button type="submit">Reset to Defaults</button>
      </Form>

      <div style={{ marginTop: "2rem" }}>
        <p>
          <a href="/">Back to Home</a>
        </p>
      </div>
    </div>
  );
});

import { routeAction$ } from "@builder.io/qwik-city";

export const useResetAction = routeAction$((_data, { cookie, redirect }) => {
  cookie.delete("user_theme", { path: "/" });
  throw redirect(302, "/theme");
});

import { component$ } from "@builder.io/qwik";
import type { DocumentHead } from "@builder.io/qwik-city";

export default component$(() => {
  return (
    <div>
      <h1>Qwik Theme Demo</h1>
      <p>
        This page demonstrates server-side theme customization using CSS custom
        properties.
      </p>
      <div class="theme-demo">
        <div class="demo-card">
          <h2>Sample Card</h2>
          <p>
            This card uses the custom theme properties: primary color, font
            size, and border radius.
          </p>
          <button class="demo-button">Themed Button</button>
        </div>
      </div>
      <p style="margin-top: 2rem;">
        <a href="/theme">Customize Theme</a>
      </p>
    </div>
  );
});

export const head: DocumentHead = {
  title: "Qwik Theme Demo",
  meta: [
    {
      name: "description",
      content: "Qwik site with customizable theme",
    },
  ],
};

/* Fallback defaults (overridden by theme-variables style tag) */
:root {
  --primary-color: #00bcd4;
  --font-size: 16px;
  --border-radius: 4px;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  font-size: var(--font-size);
  margin: 0;
  padding: 2rem;
  max-width: 800px;
  margin: 0 auto;
}

h1 {
  color: var(--primary-color);
}

a {
  color: var(--primary-color);
}

.theme-demo {
  margin-top: 2rem;
}

.demo-card {
  border: 2px solid var(--primary-color);
