/**
 * WHAT IS THIS FILE?
 *
 * SSR entry point, in all cases the application is rendered outside the browser, this
 * entry point will be the common one.
 *
 * - Server (express, cloudflare...)
 * - npm run start
 * - npm run preview
 * - npm run build
 *
 */
import {
  renderToStream,
  type RenderToStreamOptions,
} from "@builder.io/qwik/server";
import Root from "./root";

export default function (opts: RenderToStreamOptions) {
  const serverData: Record<string, any> = {
    ...opts.serverData,
  };

  // Read the user_theme cookie from the request to pass as server data
  const cookieHeader =
    opts.serverData?._requestHeaders?.cookie ||
    (opts as any).request?.headers?.get?.("cookie") ||
    "";

  const match = cookieHeader.match(/(?:^|;\s*)user_theme=([^;]*)/);
  if (match) {
    try {
      serverData.theme = JSON.parse(decodeURIComponent(match[1]));
    } catch {
      // Invalid JSON, ignore
    }
  }

  return renderToStream(<Root />, {
    ...opts,
    // Use container attributes to set attributes on the html tag.
    containerAttributes: {
      lang: "en-us",
      ...opts.containerAttributes,
    },
    serverData,
  });
}

