      return fail(400, {
        message: "invalid borderRadius",
      });
    }

    // Set the cookie
    const themeValue = JSON.stringify({
      primaryColor,
      fontSize,
      borderRadius,
    });
    cookie.set("user_theme", themeValue, { path: "/" });

    throw redirect(302, "/theme");
  },
);

export default component$(() => {
  const theme = useThemeLoader();
  const action = useThemeAction();

  return (
    <div>
